  ('RUS 101', 'Elementary Russian I', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, true),
  ('SPA 111', 'Spanish Grammar I', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, true),
