  ('GST 114', 'Communication in English II', '100 Level', 'second', 1, '', '[]'::jsonb, false),
  ('LIN 102', 'Sociolinguistics', '100 Level', 'second', 2, '', '[]'::jsonb, false),
  ('ELS 102', 'Spoken English (Practical)', '100 Level', 'second', 2, 'The course covers the theory of spoken English and the laboratory work; models/near models of speech production, and the use of recorded tapes and electronic gadgets. Also to be presented are the features of spoken English: sound articulation, vowel sounds, pure vowels and diphthongs, consonant sounds, and non-segmental features such as stress and intonation.', '["The course covers the theory of spoken English and the laboratory work","Models/near models of speech production, and the use of recorded tapes and electronic gadgets","Also to be presented are the features of spoken English: sound articulation, vowel sounds, pure vowels and diphthongs, consonant sounds, and non-segmental features such as stress and intonation"]'::jsonb, false),
  ('ELS 112', 'Introduction to Drama', '100 Level', 'second', 2, 'Students are to be introduced to the dramatic genres, with class reading of texts and seminar discussions of plays and periods. Dramatic elements are to be explained and applied to specific texts. Plays are to be as representative of the various periods as possible. Basic information will be presented about world drama, Greek drama, Roman drama, dramatic criticism, Medieval drama, the Renaissance, Restoration drama, and the Twentieth Century.', '["Students are to be introduced to the dramatic genres, with class reading of texts and seminar discussions of plays and periods","Dramatic elements are to be explained and applied to specific texts","Plays are to be as representative of the various periods as possible","Basic information will be presented about world drama, Greek drama, Roman drama, dramatic criticism, Medieval drama, the Renaissance, Restoration drama, and the Twentieth Century"]'::jsonb, false),
  ('ELS 116', 'Introduction to Poetry', '100 Level', 'second', 2, 'The course will expose the students to the practice of poetry from ancient times to the present and equip them to understand poetic terms and be able to analyse any kind of poem using these concepts. Also presented are literary periods and movements, elements of poetry, sound of poetry, kinds of poetry, and figures of speech.', '["The course will expose the students to the practice of poetry from ancient times to the present and equip them to understand poetic terms and be able to analyse any kind of poem using these concepts","Also presented are literary periods and movements, elements of poetry, sound of poetry, kinds of poetry, and figures of speech"]'::jsonb, false),
  ('ELS 118', 'Introduction to Creative Writing (Practical)', '100 Level', 'second', 2, 'Elementary aspects of creative writing are introduced in this course. There is emphasis on the approaches to developing the various genres. The students are expected to study works on how to create different literary forms.', '["Elementary aspects of creative writing are introduced in this course","There is emphasis on the approaches to developing the various genres","The students are expected to study works on how to create different literary forms"]'::jsonb, false),
  ('ELS 110', 'Introduction to Nigerian Literature', '100 Level', 'second', 2, 'This course aims to introduce students to the major literary genres of Nigerian literature, the socio-political conditions surrounding them, and such topical issues as literature and ecological change and adaptation. Attention will also be drawn to the changes in scope and preoccupation of the Nigerian literary artist over the years.', '["This course aims to introduce students to the major literary genres of Nigerian literature, the socio-political conditions surrounding them, and such topical issues as literature and ecological change and adaptation","Attention will also be drawn to the changes in scope and preoccupation of the Nigerian literary artist over the years"]'::jsonb, false),
