  ('ENT 211', 'Entrepreneurship and Innovation', '200 Level', 'first', 2, '', '[]'::jsonb, false),
  ('FAC 201', 'Digital Humanities: Application of Computer to the Arts', '200 Level', 'first', 2, '', '[]'::jsonb, false),
  ('ELS 211', 'A Survey of English Literature from Anglo-Saxon to the Elizabethan Period', '200 Level', 'first', 2, 'The course is a survey that begins with Old and Middle English literature (the extant forms; Old English heroic narrative; Old English elegy; Middle English lyric; Middle English drama; the works of Chaucer and his contemporaries) to the literatures written during the period of the accession of the Tudors and the Elizabethan period. The course will focus on literary movements, forms, themes, and major authors.', '["The course is a survey that begins with Old and Middle English literature (the extant forms","Old English heroic narrative","Old English elegy","Middle English lyric","Middle English drama","The works of Chaucer and his contemporaries) to the literatures written during the period of the accession of the Tudors and the Elizabethan period","The course will focus on literary movements, forms, themes, and major authors"]'::jsonb, false),
  ('ELS 223', 'Intermediate Grammar and Composition', '200 Level', 'first', 2, 'This course involves a detailed study of the English sentence, with the study of clause structure, sentence types and sentence patterns. It also covers summary writing, comprehension, paragraph development, essay planning, and theme development.', '["This course involves a detailed study of the English sentence, with the study of clause structure, sentence types and sentence patterns","It also covers summary writing, comprehension, paragraph development, essay planning, and theme development"]'::jsonb, false),
  ('ELS 221', 'Introduction to General Phonetics and Phonology I', '200 Level', 'first', 2, 'Language Stress Area (language stress students only). The course introduces students to the principles of phonetics and phonology, as well as description and taxonomy. Practical exercises from a variety of languages with English teaching as the focus. Laboratory uses of phonology.', '["The course introduces students to the principles of phonetics and phonology, as well as description and taxonomy","Practical exercises from a variety of languages with English teaching as the focus","Laboratory uses of phonology"]'::jsonb, false),
  ('ELS 225', 'Entrepreneurial English', '200 Level', 'first', 2, 'Language Stress Area (language stress students only). The course introduces students to digital copywriting, editorial assistance as a profession, teaching English as a foreign language, lexicography, magazine journalism, newspaper journalism, private tutoring, becoming a web manager, and publishing copyediting/proofreading.', '["The course introduces students to digital copywriting, editorial assistance as a profession, teaching English as a foreign language, lexicography, magazine journalism, newspaper journalism, private tutoring, becoming a web manager, and publishing copyediting/proofreading"]'::jsonb, false),
  ('ELS 227', 'Varieties of English Language (including English-based pidgins and creoles)', '200 Level', 'first', 2, 'Language Stress Area (language stress students only). This course is a diachronic study of the development of the English Language, from Old English to its present-day status as a world language. It will explore the evolution of varieties of English both in places where English is spoken as a native language and in regions/countries where English is non-native, including English-based Pidgins and Creoles. The linguistic and social factors that have influenced its evolution will be examined.', '["This course is a diachronic study of the development of the English Language, from Old English to its present-day status as a world language","It will explore the evolution of varieties of English both in places where English is spoken as a native language and in regions/countries where English is non-native, including English-based Pidgins and Creoles","The linguistic and social factors that have influenced its evolution will be examined"]'::jsonb, false),
  ('ELS 231', 'Entrepreneurial Literature', '200 Level', 'first', 2, 'Literature Stress Area (literature stress students only). Students are to study and be trained in Freelance Writing, web content creation, publishing and creation of e-books and journals, teaching, advertising and marketing; acquisition of self-reliance skills.', '["Students are to study and be trained in Freelance Writing, web content creation, publishing and creation of e-books and journals, teaching, advertising and marketing","Acquisition of self-reliance skills"]'::jsonb, false),
  ('ELS 235', 'The English Novel from the 19th Century', '200 Level', 'first', 2, 'Literature Stress Area (literature stress students only). History and development of the English novel; the major authors: aesthetic and thematic features of their works; basic styles and techniques of their work; critical perspectives and approaches to their work.', '["History and development of the English novel","The major authors: aesthetic and thematic features of their works","Basic styles and techniques of their work","Critical perspectives and approaches to their work"]'::jsonb, false),
  ('ELS 239', 'Literature, Popular Culture and the Mass Media', '200 Level', 'first', 2, 'Literature Stress Area (literature stress students only). The course will deal with the interface of literature (including popular literature) and the institutions of popular, folk culture, festival events, radio, television, newspapers, magazines, music, video, film, computers and the electronic media.', '["The course will deal with the interface of literature (including popular literature) and the institutions of popular, folk culture, festival events, radio, television, newspapers, magazines, music, video, film, computers and the electronic media"]'::jsonb, false),
