  ('POR 211', 'Portuguese Grammatical Structures I', '200 Level', 'first', 2, 'Elective.', '[]'::jsonb, true),
  ('RUS 201', 'Intermediate Russian I', '200 Level', 'first', 2, 'Elective.', '[]'::jsonb, true),
