  ('GST 212', 'Philosophy, Logic and Human Existence', '200 Level', 'second', 2, '', '[]'::jsonb, false),
  ('FAC 202', 'The Arts and Other Disciplines', '200 Level', 'second', 2, '', '[]'::jsonb, false),
  ('ELS 232', 'Creative Writing II', '200 Level', 'second', 2, 'Rhetoric and poetics of creative writing; practical approaches to creative writing; instruction in imaginative writing (poetry, drama and prose); devoted to seminars and workshops assisted by creative writers.', '["Rhetoric and poetics of creative writing","Practical approaches to creative writing","Instruction in imaginative writing (poetry, drama and prose)","Devoted to seminars and workshops assisted by creative writers"]'::jsonb, false),
  ('COS 304', 'Computer Applications', '200 Level', 'second', 2, '', '[]'::jsonb, false),
  ('ELS 222', 'Introduction to General Phonetics and Phonology II', '200 Level', 'second', 2, 'Language Stress Area (language stress students only). Practical examples of the application of studies in ELS 221. Advancing the application of phonetic and phonological principles. Practical laboratory exercises on languages in the context of English teaching.', '["Practical examples of the application of studies in ELS 221","Advancing the application of phonetic and phonological principles","Practical laboratory exercises on languages in the context of English teaching"]'::jsonb, false),
  ('ELS 228', 'English Morphology', '200 Level', 'second', 2, 'Language Stress Area (language stress students only). This course examines English morphological processes. Attention will be focused on morphological processes such as inflection and derivation, blending, clipping, acronyms, etc.', '["This course examines English morphological processes","Attention will be focused on morphological processes such as inflection and derivation, blending, clipping, acronyms, etc"]'::jsonb, false),
  ('ELS 224', 'Introduction to Language Theories and Analysis', '200 Level', 'second', 2, 'Language Stress Area (language stress students only). This course introduces students to various linguistic theories, approaches to language analysis, and the methodological processes of using them to analyse specific language data.', '["This course introduces students to various linguistic theories, approaches to language analysis, and the methodological processes of using them to analyse specific language data"]'::jsonb, false),
  ('ELS 226', 'Language and the Environment', '200 Level', 'second', 2, 'Language Stress Area (language stress students only). This course explores the relationship between language and the natural environment, paying particular attention to how the human ecology is represented in discourses. As part of the environmental turn in the humanities, it examines a wide range of texts from advertisements, lifestyle magazines, newspaper reports and editorials, textbooks, etc. In each case, the question is whether the stories that underlie texts encourage humans to care about people and the ecosystems that life depends on, or to destroy them. The course also aims to develop students'' awareness of the role of discourse in the area of sustainability and equip them with research and communication skills to navigate the genres of annual reports, press releases, social media, etc., used by different stakeholders to communicate their commitments, efforts, and achievements to a diverse audience (shareholders, consumers, etc.).', '["This course explores the relationship between language and the natural environment, paying particular attention to how the human ecology is represented in discourses","As part of the environmental turn in the humanities, it examines a wide range of texts from advertisements, lifestyle magazines, newspaper reports and editorials, textbooks, etc","In each case, the question is whether the stories that underlie texts encourage humans to care about people and the ecosystems that life depends on, or to destroy them","The course also aims to develop students'' awareness of the role of discourse in the area of sustainability and equip them with research and communication skills to navigate the genres of annual reports, press releases, social media, etc., used by different stakeholders to communicate their commitments, efforts, and achievements to a diverse audience (shareholders, consumers, etc.)"]'::jsonb, false),
  ('ELS 234', 'Introduction to Contemporary African Drama', '200 Level', 'second', 2, 'Literature Stress Area (literature stress students only). This course exposes students to contemporary works in African drama. A selection of contemporary African texts is studied vis-a-vis their thematic preoccupation, style and structural distinctiveness. Their identification with traditional drama will also be discussed.', '["This course exposes students to contemporary works in African drama","A selection of contemporary African texts is studied vis-a-vis their thematic preoccupation, style and structural distinctiveness","Their identification with traditional drama will also be discussed"]'::jsonb, false),
  ('ELS 236', 'Introduction to English Poetry', '200 Level', 'second', 2, 'Literature Stress Area (literature stress students only). English poetry from the Romantics to the 20th century. The poetry of the Romantic period. Victorian poetry, Augustan and metaphysical poets.', '["English poetry from the Romantics to the 20th century","The poetry of the Romantic period","Victorian poetry, Augustan and metaphysical poets"]'::jsonb, false),
  ('ELS 238', 'Modern English Drama', '200 Level', 'second', 2, 'Literature Stress Area (literature stress students only). Major dramatists and playwrights of the modern age. Works from T. S. Eliot and Ezra Pound to mid-20th century drama. Study of sample authors and their texts. Critical and theoretical studies of the period.', '["Major dramatists and playwrights of the modern age","Works from T","Eliot and Ezra Pound to mid-20th century drama","Study of sample authors and their texts","Critical and theoretical studies of the period"]'::jsonb, false),
  ('ELS 230', 'Literature and the Environment', '200 Level', 'second', 2, 'Literature Stress Area (literature stress students only). This course will explore environmental awareness in literary works, with a focus on pastoral literature in which the characters and their actions are, to some degree, in harmony with the environment. It will also explore changes in attitude going back to the Industrial Revolution, when the human impact began to register negatively in literature.', '["This course will explore environmental awareness in literary works, with a focus on pastoral literature in which the characters and their actions are, to some degree, in harmony with the environment","It will also explore changes in attitude going back to the Industrial Revolution, when the human impact began to register negatively in literature"]'::jsonb, false),
  ('FRE 202', 'Intermediate French II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('GER 202', 'Intermediate German II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('POR 212', 'Portuguese Grammatical Structures II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('RUS 202', 'Intermediate Russian II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('SPA 212', 'Spanish Grammatical Structures II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('SWA 212', 'Swahili Grammatical Structures II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('IGB 202', 'Intermediate Igbo II', '200 Level', 'second', 2, 'Elective.', '[]'::jsonb, true),
  ('GST 311', 'Peace and Conflict Studies I', '300 Level', 'first', 1, '', '[]'::jsonb, false),
  ('FAC 301', 'Research Methodology in the Arts', '300 Level', 'first', 2, '', '[]'::jsonb, false),
  ('ELS 301', 'The English Language in Nigeria', '300 Level', 'first', 2, 'History of English in Nigeria. Emergence of Englishes and the evolution of a Nigerian standard. Distinctive properties of Nigerian Languages and their impact on performance in standard English.', '["History of English in Nigeria","Emergence of Englishes and the evolution of a Nigerian standard","Distinctive properties of Nigerian Languages and their impact on performance in standard English"]'::jsonb, false),
  ('ELS 321', 'Advanced English Composition I', '300 Level', 'first', 2, 'The course aims at developing the students'' skills in high-level essay writing, with emphasis on originality of style and thought. The topics to be covered include choice of words, idioms and expressions, appropriateness of language to the addressee; different types of sentences; effective use of punctuation for sentence control; queries, reported speech; report writing; the writing of minutes; the long essay; speech writing, letters; invitations, public announcements, and memoranda.', '["The course aims at developing the students'' skills in high-level essay writing, with emphasis on originality of style and thought","The topics to be covered include choice of words, idioms and expressions, appropriateness of language to the addressee","Different types of sentences","Effective use of punctuation for sentence control","Queries, reported speech","Report writing","The writing of minutes","The long essay","Speech writing, letters","Invitations, public announcements, and memoranda"]'::jsonb, false),
  ('ELS 323', 'Introduction to Semantics', '300 Level', 'first', 2, 'Language Stress Area (language stress students only). The course will present the scope of the problem of meaning and the traditional explanations of meaning based on reference and image. Analysis of meaning based on the concept and the speech situation; Saussure''s sign theory; generative semantics; functionalism; inter-lexical relations; pragmatics; and language use.', '["The course will present the scope of the problem of meaning and the traditional explanations of meaning based on reference and image","Analysis of meaning based on the concept and the speech situation","Saussure''s sign theory","Generative semantics","Functionalism","Inter-lexical relations","Pragmatics","And language use"]'::jsonb, false),
  ('ELS 325', 'Phonology of English', '300 Level', 'first', 2, 'Language Stress Area (language stress students only). This course begins with the study of discrete sound segments and the acceptable sequences in syllables; the concept of the phoneme and allophone; sound patterns in connected speech with emphasis on stress, rhythm and intonation; and elementary concepts in generative phonology.', '["This course begins with the study of discrete sound segments and the acceptable sequences in syllables","The concept of the phoneme and allophone","Sound patterns in connected speech with emphasis on stress, rhythm and intonation","And elementary concepts in generative phonology"]'::jsonb, false),
  ('ELS 327', 'The Sociolinguistics of English', '300 Level', 'first', 2, 'Language Stress Area (language stress students only). This course will first provide a basic introduction to the history, methodology, theoretical thrust, basic concerns and applications of sociolinguistics. It will then examine the differentiation based on English in post-colonial countries like Nigeria, the power of English, English and multilingualism, English and globalisation, English and national development, English and global identity, attitudes towards English, the individual and societal functions of English in a second-language context like Nigeria, including its role as a lingua franca, as an official language, etc.', '["This course will first provide a basic introduction to the history, methodology, theoretical thrust, basic concerns and applications of sociolinguistics","It will then examine the differentiation based on English in post-colonial countries like Nigeria, the power of English, English and multilingualism, English and globalisation, English and national development, English and global identity, attitudes towards English, the individual and societal functions of English in a second-language context like Nigeria, including its role as a lingua franca, as an official language, etc"]'::jsonb, false),
  ('ELS 329', 'Language and National Development', '300 Level', 'first', 2, 'Language Stress Area (language stress students only). This course teaches national development, with a focus on the constraints placed on national development by the linguistic situation in developing African nations, language being the most effective means of human communication and also the cornerstone of mass participation in the development process itself.', '["This course teaches national development, with a focus on the constraints placed on national development by the linguistic situation in developing African nations, language being the most effective means of human communication and also the cornerstone of mass participation in the development process itself"]'::jsonb, false),
  ('ELS 331', 'Modern African Drama', '300 Level', 'first', 2, 'Literature Stress Area (literature stress students only). This course focuses on the evolution of dramatic literature in Africa, paying special attention to works of the major dramatists in each of the main regions of the Continent; issues of form and aesthetics in modern African drama.', '["This course focuses on the evolution of dramatic literature in Africa, paying special attention to works of the major dramatists in each of the main regions of the Continent","Issues of form and aesthetics in modern African drama"]'::jsonb, false),
  ('ELS 333', 'Introduction to Literary Criticism/Theories', '300 Level', 'first', 2, 'Literature Stress Area (literature stress students only). The distinctive forms of writing produced by literary scholars will be presented; the contributing and shaping factors in this writing will be seen; thus the nexus to literary theory, literary history, and poetics will be presented; the contributions of the twentieth century in the development of criticism, and the trends, including deconstruction, hermeneutics, philology, and textuality/intertextual analyses.', '["The distinctive forms of writing produced by literary scholars will be presented","The contributing and shaping factors in this writing will be seen","Thus the nexus to literary theory, literary history, and poetics will be presented","The contributions of the twentieth century in the development of criticism, and the trends, including deconstruction, hermeneutics, philology, and textuality/intertextual analyses"]'::jsonb, false),
  ('ELS 335', 'Modern African Prose Fiction', '300 Level', 'first', 2, 'Literature Stress Area (literature stress students only). A study of novels by African authors dealing with African themes, life and experience. The course will cover the major regions of the continent; the representative novelists of each region, and their works.', '["A study of novels by African authors dealing with African themes, life and experience","The course will cover the major regions of the continent; the representative novelists of each region, and their works"]'::jsonb, false),
  ('ELS 337', 'Folklore in African Literature I', '300 Level', 'first', 2, 'Literature Stress Area (literature stress students only). This course is focused on Oral Literature and the exploration of oral folkloric elements; Oral resources as provenance for written African literature; Oral performance in contemporary literary texts; and performance of both oral and written texts.', '["This course is focused on Oral Literature and the exploration of oral folkloric elements","Oral resources as provenance for written African literature","Oral performance in contemporary literary texts","And performance of both oral and written texts"]'::jsonb, false),
  ('GST 312', 'Peace and Conflict Resolution II', '300 Level', 'second', 1, '', '[]'::jsonb, false),
  ('ENT 312', 'Venture Creation', '300 Level', 'second', 2, '', '[]'::jsonb, false),
  ('FAC 302', 'Theory in the Humanities', '300 Level', 'second', 2, '', '[]'::jsonb, false),
  ('ELS 302', 'Discourse Analysis', '300 Level', 'second', 3, 'The course will cover the concept of discourse as it relates to everyday language use and understanding, discourse theories, techniques of discourse analysis, the characteristics of discourse, kinds of discourse, the persons of discourse, system texts and textuality, discursive formations and genres, the correlates of discourse, and the instance of discourse. Emphasis will be on practical analysis and description of relevant textual materials such as advertisements, obituaries, cartoons, literary texts, greetings, etc. The course will also pay attention to principles and practice of Discourse Analysis, features of coherence and cohesion, functions of linking devices, and intra- and inter-sentential paragraph devices in texts.', '["The course will cover the concept of discourse as it relates to everyday language use and understanding, discourse theories, techniques of discourse analysis, the characteristics of discourse, kinds of discourse, the persons of discourse, system texts and textuality, discursive formations and genres, the correlates of discourse, and the instance of discourse","Emphasis will be on practical analysis and description of relevant textual materials such as advertisements, obituaries, cartoons, literary texts, greetings, etc","The course will also pay attention to principles and practice of Discourse Analysis, features of coherence and cohesion, functions of linking devices, and intra- and inter-sentential paragraph devices in texts"]'::jsonb, false),
  ('ELS 340', 'Research Methods', '300 Level', 'second', 3, 'The learning activities in this course centre on the choice of research topic, identification and statement of the problem, methods of investigation, data collection, analysis, and compilation, acknowledgement and documentation, project format, writing up, and proofreading.', '["The learning activities in this course centre on the choice of research topic, identification and statement of the problem, methods of investigation, data collection, analysis, and compilation, acknowledgement and documentation, project format, writing up, and proofreading"]'::jsonb, false),
  ('ELS 324', 'Language and Society', '300 Level', 'second', 3, 'Language Stress Area (language stress students only). Language in a social context. Linguistic and social categories of language. Grammar of social interactions and movements. Theories and concepts of language usage, e.g., womanism, feminism, Marxism, gender, etc. Language change, attitude, identity, and education. Language and socioeconomic categories. Multilingualism.', '["Language in a social context","Linguistic and social categories of language","Grammar of social interactions and movements","Theories and concepts of language usage, e.g., womanism, feminism, Marxism, gender, etc","Language change, attitude, identity, and education","Language and socioeconomic categories","Multilingualism"]'::jsonb, false),
  ('ELS 326', 'Introduction to Applied Linguistics', '300 Level', 'second', 2, 'Language Stress Area (language stress students only). Application of linguistic knowledge to language phenomena; analysis: contrastive, error, discourse, and performance; acquisition of language in L1 and L2 situations; language teaching, learning and testing; psychology and sociology of language acquisition and development; deploying practical relevance of linguistics to computer language instruction, speed effect and artificial intelligence.', '["Application of linguistic knowledge to language phenomena","Analysis: contrastive, error, discourse, and performance","Acquisition of language in L1 and L2 situations","Language teaching, learning and testing","Psychology and sociology of language acquisition and development","Deploying practical relevance of linguistics to computer language instruction, speed effect and artificial intelligence"]'::jsonb, false),
  ('ELS 322', 'History of English', '300 Level', 'second', 2, 'Language Stress Area (language stress students only). A survey of the early development of the English language; the evolution of Old English lexis, phonology, and grammar; the development of the English language in more recent times; spread to America and the Commonwealth; dialectal varieties of English; the different national standards of English: American English, Nigerian English, and others.', '["A survey of the early development of the English language","The evolution of Old English lexis, phonology, and grammar","The development of the English language in more recent times","Spread to America and the Commonwealth","Dialectal varieties of English","The different national standards of English: American English, Nigerian English, and others"]'::jsonb, false),
  ('ELS 332', 'Nigerian Oral Literatures in English Translation (to include Fieldwork Project and Presentation)', '300 Level', 'second', 2, 'Literature Stress Area (literature stress students only). Translations of oral literature into English; fieldwork research, data collection, translations and their classification. Analysis of collected samples. Reconstruction of literary histories from collected tales. Locate the genres of oral literature from various indigenous polities and languages.', '["Translations of oral literature into English; fieldwork research, data collection, translations and their classification","Analysis of collected samples","Reconstruction of literary histories from collected tales","Locate the genres of oral literature from various indigenous polities and languages"]'::jsonb, false),
  ('ELS 336', 'Modern African Poetry', '300 Level', 'second', 2, 'Literature Stress Area (literature stress students only). This is a survey course. The course discusses representative poetic works from the African Continent from the early Twentieth Century to the present, along with the ideas and ideologies historically associated with African poetry: nationalism, negritude, protest, socialism, feminism, and formalism. The course is divided into periods: the Beginnings, the 1960s and the psychology of disillusionment; protest/poetry of conflict; the self-conscious lyric.', '["This is a survey course","The course discusses representative poetic works from the African Continent from the early Twentieth Century to the present, along with the ideas and ideologies historically associated with African poetry: nationalism, negritude, protest, socialism, feminism, and formalism","The course is divided into periods: the Beginnings, the 1960s and the psychology of disillusionment","Protest/poetry of conflict","The self-conscious lyric"]'::jsonb, false),
  ('ELS 338', 'Chinua Achebe Studies', '300 Level', 'second', 3, 'Literature Stress Area (literature stress students only). The works of Chinua Achebe will be fully covered in this course: the novels, literary criticism, children''s literature, poetry and short stories; his socially and politically significant contributions will also be explored, as well as the nature of his contribution to world literature and African letters. The course will also examine his leadership in the culture industry.', '["The works of Chinua Achebe will be fully covered in this course: the novels, literary criticism, children''s literature, poetry and short stories","His socially and politically significant contributions will also be explored, as well as the nature of his contribution to world literature and African letters","The course will also examine his leadership in the culture industry"]'::jsonb, false),
  ('ELS 425', 'Stylistics', '400 Level', 'first', 3, 'The emphasis will be on the theories of style, contrasting affective Stylistics and the critical theory of style. The course will also involve a study of style in relation to the different kinds of text; style and the literary work of art and levels of analysis, in terms of linguistic properties and in terms of literary properties.', '["The emphasis will be on the theories of style, contrasting affective Stylistics and the critical theory of style","The course will also involve a study of style in relation to the different kinds of text","Style and the literary work of art and levels of analysis, in terms of linguistic properties and in terms of literary properties"]'::jsonb, false),
  ('ELS 433', 'Literature and Gender Studies', '400 Level', 'first', 3, 'Women''s contribution to the literatures of their times will be in focus in this course; also to be explored is to what extent contrasting patterns exist in the portrayal of male and female characters in literary works by people of different genders.', '["Women''s contribution to the literatures of their times will be in focus in this course","Also to be explored is to what extent contrasting patterns exist in the portrayal of male and female characters in literary works by people of different genders"]'::jsonb, false),
  ('ELS 421', 'Pragmatics', '400 Level', 'first', 3, 'Language Stress Area (language stress students only). The course focuses on the scope, goals and principles of pragmatics. Particular attention will be paid to utterance meaning as distinct from sentence meaning. The socio-cultural and linguistic variables that determine current interpretation of terms in the real world, presupposition, context, locutionary, illocutionary and perlocutionary acts, speech acts in general, intention, inference, conventional and conversational implicatures, and emerging theories of pragmatics.', '["The course focuses on the scope, goals and principles of pragmatics","Particular attention will be paid to utterance meaning as distinct from sentence meaning","The socio-cultural and linguistic variables that determine current interpretation of terms in the real world, presupposition, context, locutionary, illocutionary and perlocutionary acts, speech acts in general, intention, inference, conventional and conversational implicatures, and emerging theories of pragmatics"]'::jsonb, false),
  ('ELS 427', 'Psycholinguistics', '400 Level', 'first', 3, 'Language Stress Area (language stress students only). This course presents the psycholinguist''s account of language and the relationship between language and mind. Topics covered include language acquisition and language learning; language, thinking and cognition; language and the brain, language localisation; linguistic performance and behaviour, production and comprehension; language impairments.', '["This course presents the psycholinguist''s account of language and the relationship between language and mind","Topics covered include language acquisition and language learning","Language, thinking and cognition","Language and the brain, language localisation","Linguistic performance and behaviour, production and comprehension","Language impairments"]'::jsonb, false),
  ('ELS 423', 'Language and Digital Technologies', '400 Level', 'first', 3, 'Language Stress Area (language stress students only). This course aims to familiarise students with the range of issues and topics related to the interaction between human language and digital technologies, with emphasis on communication in digital contexts, the emerging field of language and Artificial Intelligence (AI), and natural language processing. It also introduces students to digital discourse, corpus linguistics, and the sociolinguistics of online communication, particularly within Nigerian and global multilingual settings. Students will critically examine digital language practices and possibly gain practical skills in digital tools for language research.', '["This course aims to familiarise students with the range of issues and topics related to the interaction between human language and digital technologies, with emphasis on communication in digital contexts, the emerging field of language and Artificial Intelligence (AI), and natural language processing","It also introduces students to digital discourse, corpus linguistics, and the sociolinguistics of online communication, particularly within Nigerian and global multilingual settings","Students will critically examine digital language practices and possibly gain practical skills in digital tools for language research"]'::jsonb, false),
  ('ELS 429', 'Syntax of English', '400 Level', 'first', 2, 'Language Stress Area (language stress students only). This course will expose students to the principles and practices of basic syntactic models such as the traditional, structuralist, transformational-generative and systemic-functional models. These will be discussed with reference to English.', '["This course will expose students to the principles and practices of basic syntactic models such as the traditional, structuralist, transformational-generative and systemic-functional models","These will be discussed with reference to English"]'::jsonb, false),
  ('ELS 431', 'Creative Writing III', '400 Level', 'first', 3, 'Literature Stress Area (literature stress students only). Intensive practical course in creative writing (Continuation of ELS 232). Active creative works by students in the major literary genre. Develop enduring skills in imaginative works.', '["Intensive practical course in creative writing (Continuation of ELS 232)","Active creative works by students in the major literary genre","Develop enduring skills in imaginative works"]'::jsonb, false),
  ('ELS 435', 'African-American and Caribbean Literature', '400 Level', 'first', 3, 'Literature Stress Area (literature stress students only). The aim is to expose students to a more intimate study of selected African-American and Caribbean writers, paying attention to the forms as well as the inspiring political, social and existential issues of the works.', '["The aim is to expose students to a more intimate study of selected African-American and Caribbean writers, paying attention to the forms as well as the inspiring political, social and existential issues of the works"]'::jsonb, false),
  ('ELS 437', 'Advanced Literary Theory and Criticism', '400 Level', 'first', 3, 'Literature Stress Area (literature stress students only). This course is concerned with the philosophical inquiry into the understanding of literary art as it has been undertaken since the modernist revolution, deriving mainly from the theories of Marx, Nietzsche, Freud, and Husserlian phenomenology, Derrida, Bakhtin, Foucault, Barthes and so on; theory and ideologies. The course will also cover formalism, structuralism, post-structuralism, and the feminist movement.', '["This course is concerned with the philosophical inquiry into the understanding of literary art as it has been undertaken since the modernist revolution, deriving mainly from the theories of Marx, Nietzsche, Freud, and Husserlian phenomenology, Derrida, Bakhtin, Foucault, Barthes and so on","Theory and ideologies","The course will also cover formalism, structuralism, post-structuralism, and the feminist movement"]'::jsonb, false),
  ('ELS 439', 'Foundations to Comparative Literature', '400 Level', 'first', 2, 'Literature Stress Area (literature stress students only). This course focuses on the basic notions in comparative literature. Brief history of comparative literature. Goethe and the concept of world literature. Schools of comparative literature. The American School. The French School. The Great Tradition. The language debate. Translation and world literature. The universals in art. Principles of comparative studies. Approaches in comparative analysis. Comparative poetry. Comparative drama. Narrative in comparative studies. Critique of contemporary world literature programmes. Comparative literature and advances in criticism.', '["This course focuses on the basic notions in comparative literature","Brief history of comparative literature","Goethe and the concept of world literature","Schools of comparative literature","The American School","The French School","The Great Tradition","The language debate","Translation and world literature","The universals in art","Principles of comparative studies","Approaches in comparative analysis","Comparative poetry","Comparative drama","Narrative in comparative studies","Critique of contemporary world literature programmes","Comparative literature and advances in criticism"]'::jsonb, false),
  ('ELS 490', 'Project', '400 Level', 'second', 6, 'The research project is a key element in finishing and rounding off the student for graduation. The student is guided by a senior academic and experienced researcher in the discipline area in the discovery of problems in the discipline, the description and investigation of these problems, data collection, analysis, and collation, and the methods of documentation in the discipline.', '["The research project is a key element in finishing and rounding off the student for graduation","The student is guided by a senior academic and experienced researcher in the discipline area in the discovery of problems in the discipline, the description and investigation of these problems, data collection, analysis, and collation, and the methods of documentation in the discipline"]'::jsonb, false),
  ('ELS 422', 'Multilingualism', '400 Level', 'second', 3, 'Language Stress Area (language stress students only). This course focuses on multilingualism in general and English and multilingualism in particular. Specific attention will be drawn to the position of English in multilingual African and other nations. Topics such as language choice, minority languages, language planning and management in the Nigerian multilingual context will be critically examined from the perspective of the roles of English and Nigeria''s indigenous languages.', '["This course focuses on multilingualism in general and English and multilingualism in particular","Specific attention will be drawn to the position of English in multilingual African and other nations","Topics such as language choice, minority languages, language planning and management in the Nigerian multilingual context will be critically examined from the perspective of the roles of English and Nigeria''s indigenous languages"]'::jsonb, false),
  ('ELS 424', 'English for Specific Purposes', '400 Level', 'second', 3, 'Language Stress Area (language stress students only). This is concerned with the ways in which English may be adapted to particular circumstances and purposes, with emphasis on specialised varieties of English, the language of journalism, science and technology, public speaking, ordinary conversation, English for academic purposes, etc. Students are to write a short project involving fieldwork on any of the areas covered.', '["This is concerned with the ways in which English may be adapted to particular circumstances and purposes, with emphasis on specialised varieties of English, the language of journalism, science and technology, public speaking, ordinary conversation, English for academic purposes, etc","Students are to write a short project involving fieldwork on any of the areas covered"]'::jsonb, false),
  ('ELS 426', 'Survey of the English Language in Africa', '400 Level', 'second', 3, 'Language Stress Area (language stress students only). This course is a survey of the English language as used in West Africa, East, North and Southern Africa. It pays attention to the history of the English language in the regions, its functions and varieties across the regions.', '["This course is a survey of the English language as used in West Africa, East, North and Southern Africa","It pays attention to the history of the English language in the regions, its functions and varieties across the regions"]'::jsonb, false),
  ('ELS 432', 'Prose Fiction', '400 Level', 'second', 3, 'Literature Stress Area (literature stress students only). The course is organised to demonstrate the historical as well as the aesthetic evolution of the novel as a dominant literary genre, closest to human experience. Representative novels are selected from each century.', '["The course is organised to demonstrate the historical as well as the aesthetic evolution of the novel as a dominant literary genre, closest to human experience","Representative novels are selected from each century"]'::jsonb, false),
  ('ELS 434', 'Commonwealth Literature', '400 Level', 'second', 3, 'Literature Stress Area (literature stress students only). This course will concentrate on a study of the major themes and literary trends in the following areas of the Commonwealth: Australia, Canada, India, New Zealand and the West Indies. An attempt will be made to determine the issues common to writers in the Commonwealth. The course will be thematically organised and will examine, among other things, the problem of language in creative writing in the Commonwealth.', '["This course will concentrate on a study of the major themes and literary trends in the following areas of the Commonwealth: Australia, Canada, India, New Zealand and the West Indies","An attempt will be made to determine the issues common to writers in the Commonwealth","The course will be thematically organised and will examine, among other things, the problem of language in creative writing in the Commonwealth"]'::jsonb, false),
  ('ELS 436', 'American Literature Survey: The Beginnings to the Modern Period', '400 Level', 'second', 3, 'Literature Stress Area (literature stress students only). A selection of American poetry, prose, and drama from the Colonial times to the early 20th Century. Emphasis is on the socio-political climate that stimulated such literary types as Realism, Regionalism, and Naturalism; periods such as the Gilded Age, primitivism, etc.', '["A selection of American poetry, prose, and drama from the Colonial times to the early 20th Century","Emphasis is on the socio-political climate that stimulated such literary types as Realism, Regionalism, and Naturalism","Periods such as the Gilded Age, primitivism, etc"]'::jsonb, false)
)
insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name, is_elective)
select s.course_code, s.course_title, 'University of Nigeria, Nsukka', 'Faculty of Arts',
       'English and Literary Studies', s.level, s.semester, s.credit_units,
       s.description, s.topics, 'CCMAS 2026 Handbook (ELS)', s.is_elective
  from src s
 where not exists (
   select 1 from public.course_outlines c
    where c.institution = 'University of Nigeria, Nsukka'
      and c.department = 'English and Literary Studies'
      and c.course_code = s.course_code
      and c.course_title = s.course_title
      and c.level = s.level);

-- Borrow real descriptions/topics for ancillary courses already described
-- elsewhere in the app (same course code). Only fills rows that are still empty.
update public.course_outlines t
   set description = case when t.is_elective and t.description = 'Elective.'
                          then 'Elective. ' || b.description else b.description end,
       topics = b.topics
  from (
    select distinct on (course_code) course_code, description, topics
      from public.course_outlines
     where length(description) >= 40
       and course_code in ('GST 111','GST 114','GST 211','GST 212','GST 311','GST 312',
                           'COS 101','COS 304','GSP 105','GSP 106',
                           'ENT 211','ENT 312')
       and department <> 'English and Literary Studies'
     order by course_code, length(description) desc
  ) b
 where t.institution = 'University of Nigeria, Nsukka'
   and t.department = 'English and Literary Studies'
   and t.contributor_name = 'CCMAS 2026 Handbook (ELS)'
   and t.course_code = b.course_code
   and (t.description = '' or t.description = 'Elective.')
   and t.topics = '[]'::jsonb;
